INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist die Durchführung eine eigenständige Phase im Projektmanagement?', 2, '[{"text": "Ja", "correct": true, "because": "Folgt der Planung"}, {"text": "Nein", "correct": false, "because": "Sie ist zentral"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolgt die Durchführungsphase?', 3, '[{"text": "Umsetzung der Planung", "correct": true, "because": "Setzt Plan in Aktion"}, {"text": "Team motivieren", "correct": false, "because": "Nebenaspekt"}, {"text": "Kosten direkt senken", "correct": false, "because": "Kein primäres Ziel"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Die Durchführung realisiert Arbeitspakete. b) Sie erfolgt vor der Planung.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, Planung ist vorher"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist nicht korrekt"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist zutreffend"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aktivitäten gehören zur Durchführung?', 4, '[{"text": "Ausführung von Aufgaben", "correct": true, "because": "Realisiert Plan"}, {"text": "Unklare Anweisungen", "correct": false, "because": "Widerspricht Ziel"}, {"text": "Überwachung des Fortschritts", "correct": true, "because": "Kontrolliert Ablauf"}, {"text": "Koordination des Teams", "correct": true, "because": "Sichert Zusammenarbeit"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann ein Projekt ohne Durchführung erfolgreich sein?', 2, '[{"text": "Nein", "correct": true, "because": "Umsetzung fehlt"}, {"text": "Ja", "correct": false, "because": "Plan bleibt Theorie"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rolle spielt die Durchführung im Projekt?', 3, '[{"text": "Umsetzung der Planung in Ergebnisse", "correct": true, "because": "Macht Plan real"}, {"text": "Ziele neu definieren", "correct": false, "because": "Initiierungsschritt"}, {"text": "Kosten neu kalkulieren", "correct": false, "because": "Planungsaspekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist die Durchführung nur für technische Projekte relevant?', 2, '[{"text": "Nein", "correct": true, "because": "Gilt für alle Projekte"}, {"text": "Ja", "correct": false, "because": "Universelle Phase"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Werkzeug unterstützt die Durchführung?', 3, '[{"text": "Projektmanagement-Software", "correct": true, "because": "Überwacht Fortschritt"}, {"text": "Keine Dokumentation", "correct": false, "because": "Fehlt Übersicht"}, {"text": "Zufällige Notizen", "correct": false, "because": "Unstrukturiert"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Die Durchführung folgt dem Zeitplan. b) Sie ist immer problemlos.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, Probleme möglich"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist nicht korrekt"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist zutreffend"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was passiert ohne Durchführung?', 3, '[{"text": "Projekt bleibt unvollendet", "correct": true, "because": "Keine Umsetzung"}, {"text": "Planung wird effizienter", "correct": false, "because": "Kein Zusammenhang"}, {"text": "Kosten sinken", "correct": false, "because": "Planung nutzlos"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann die Durchführung ohne Planung starten?', 2, '[{"text": "Nein", "correct": true, "because": "Basis fehlt"}, {"text": "Ja", "correct": false, "because": "Chaos droht"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Beispiel zeigt eine Durchführungsaktivität?', 3, '[{"text": "Server gemäß Plan installieren", "correct": true, "because": "Konkret und real"}, {"text": "Irgendwas machen", "correct": false, "because": "Zu vage"}, {"text": "Team soll schneller sein", "correct": false, "because": "Keine Aufgabe"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist die Durchführung nur für den Projektleiter relevant?', 2, '[{"text": "Nein", "correct": true, "because": "Team führt aus"}, {"text": "Ja", "correct": false, "because": "Projektweite Bedeutung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren beeinflussen die Durchführung?', 4, '[{"text": "Ressourcenverfügbarkeit", "correct": true, "because": "Bestimmt Umsetzung"}, {"text": "Unklare Ziele", "correct": false, "because": "Erschweren Arbeit"}, {"text": "Zeitplan", "correct": true, "because": "Steuert Ablauf"}, {"text": "Teamkommunikation", "correct": true, "because": "Fördert Koordination"}]'),
('00000000-0000-0000-0000-000000000000', 'Muss die Durchführung dokumentiert werden?', 2, '[{"text": "Ja", "correct": true, "because": "Fortschritt nachvollziehbar"}, {"text": "Nein", "correct": false, "because": "Dokumentation hilft"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rolle spielt die Durchführung?', 3, '[{"text": "Projektziele realisieren", "correct": true, "because": "Macht Plan konkret"}, {"text": "Ziele neu definieren", "correct": false, "because": "Initiierungsschritt"}, {"text": "Planung überarbeiten", "correct": false, "because": "Später möglich"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann die Durchführung ohne Arbeitspakete erfolgen?', 2, '[{"text": "Nein", "correct": true, "because": "Aufgabenbasis fehlt"}, {"text": "Ja", "correct": false, "because": "Unstrukturiert"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Faktor erschwert die Durchführung?', 3, '[{"text": "Fehlende Ressourcen", "correct": true, "because": "Verzögern Arbeit"}, {"text": "Klarer Zeitplan", "correct": false, "because": "Fördert Ablauf"}, {"text": "Gute Koordination", "correct": false, "because": "Unterstützt Prozess"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Die Durchführung erfordert Kontrolle. b) Sie ist nur für große Projekte.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, breit anwendbar"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist nicht korrekt"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist zutreffend"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist ein Nutzen der Durchführung?', 3, '[{"text": "Projektfortschritt sichern", "correct": true, "because": "Ergebnisse liefern"}, {"text": "Maximale Unklarheit", "correct": false, "because": "Widerspricht Zweck"}, {"text": "Keine Koordination", "correct": false, "because": "Fördert Zusammenarbeit"}]');
